package com.mediconnect.appointment.application;
import java.time.*; import com.mediconnect.shared.exception.*; import org.springframework.stereotype.Component;
@Component public class AppointmentPolicy { private final Clock clock; public AppointmentPolicy(Clock clock){this.clock=clock;} public void validateBookingWindow(Instant startTime,Instant endTime){Instant now=clock.instant();if(!endTime.isAfter(startTime))throw new BusinessRuleException("Appointment end time must be after its start time.");if(!startTime.isAfter(now))throw new BusinessRuleException("Appointments must be scheduled in the future.");} public void validatePatientCancellation(Instant appointmentStart){Duration remaining=Duration.between(clock.instant(),appointmentStart);if(remaining.compareTo(Duration.ofHours(24))<=0)throw new LateCancellationException("Patients can cancel autonomously only when more than 24 hours remain before the appointment.");} }
